import{_ as o,o as a,c,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const _=JSON.parse('{"title":"llm_reco — 大模型推荐角色（知识库与推理工作区）","description":"","frontmatter":{},"headers":[],"relativePath":"llm_reco/README.md","filePath":"llm_reco/README.md"}'),r={name:"llm_reco/README.md"};function l(t,e,i,m,n,s){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="llm-reco-—-大模型推荐角色-知识库与推理工作区" tabindex="-1">llm_reco — 大模型推荐角色（知识库与推理工作区） <a class="header-anchor" href="#llm-reco-—-大模型推荐角色-知识库与推理工作区" aria-label="Permalink to &quot;llm_reco — 大模型推荐角色（知识库与推理工作区）&quot;">​</a></h1><p>本文件夹用于支撑「大模型推荐角色」页面（<code>site/zh/llm-recommend.md</code> + <code>site/ja/llm-recommend.md</code>）。 页面<strong>默认隐藏</strong>（不进 registry / 侧边栏），仅可通过直接输入 URL 访问，待推荐质量稳定后再正式发布。</p><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>由大模型阅读全部角色详情页（属性 / 必杀技 / 固有效果）与系统·装备·道具类页面 （养成、战斗机制、装备、重要副本），给出<strong>带理由的角色推荐</strong>。</p><h2 id="文件夹结构" tabindex="-1">文件夹结构 <a class="header-anchor" href="#文件夹结构" aria-label="Permalink to &quot;文件夹结构&quot;">​</a></h2><ul><li><code>README.md</code>：本说明。</li><li><code>extract_chars.py</code>：从 <code>data/parsed/characters/*.json</code> 抽取全部角色关键数据 → <code>char_data.json</code>。</li><li><code>char_data.json</code>：所有角色的结构化数据（稀有度 / 元素 / 攻防魔抗 / 必杀技 / 固有效果 / 获取方式）。</li><li><code>game-mechanics.md</code>：阅读系统·装备·道具页后整理的游戏机制理解（战斗、养成、装备、副本）。</li><li><code>reco-draft.md</code>：<strong>推荐推理工作稿</strong>（按角色/定位分组，每条含推荐理由）；用户在此纠正，我据此修正。</li><li><code>reco-method.md</code>：推荐评价维度与权重（用户可一并纠正“该用什么标准推荐”）。</li></ul><h2 id="协作方式-与用户" tabindex="-1">协作方式（与用户） <a class="header-anchor" href="#协作方式-与用户" aria-label="Permalink to &quot;协作方式（与用户）&quot;">​</a></h2><ol><li>我基于 <code>char_data.json</code> + <code>game-mechanics.md</code> 在 <code>reco-draft.md</code> 写推荐与理由。</li><li>用户阅读后纠正（例如“XX 不该推荐，因为…”“标准里应更看重…”）→ 在 <code>reco-draft.md</code> / <code>reco-method.md</code> 批注或告诉我。</li><li>我修改推理与页面内容，重新生成 <code>site/*/llm-recommend.md</code>。</li></ol><h2 id="重抽取" tabindex="-1">重抽取 <a class="header-anchor" href="#重抽取" aria-label="Permalink to &quot;重抽取&quot;">​</a></h2><p>角色数据随 wiki 更新变化，重跑：<code>python llm_reco/extract_chars.py</code></p>',10)])])}const p=o(r,[["render",l]]);export{_ as __pageData,p as default};
